package org.brightstats.desktop;
import java.nio.file.*;import java.util.*;import com.google.gson.*;import javafx.application.*;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.concurrent.*;import javafx.stage.Stage;import org.brightstats.data.*;import org.brightstats.report.*;
public final class ProductivityUpgradeChecks extends Application {
 static int checks;static Throwable failure;Stage stage;Path out;final JsonObject measurements=new JsonObject();final CalculationProgressView progress=new CalculationProgressView();
 static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 public void start(Stage stage){this.stage=stage;try{out=Path.of(getParameters().getRaw().getFirst());Files.createDirectories(out);UiAppearance.install(UserPreferences.defaults());stage.setScene(new Scene(new BorderPane(),1100,780));stage.show();var examples=StudioExamples.all();List<StudioExamples.Example> opened=new ArrayList<>();Parent home=(Parent)StudioHome.create(()->{},()->{},()->{},()->{},()->{},()->{},opened::add);stage.getScene().setRoot(home);home.applyCss();home.layout();List<Button> buttons=home.lookupAll(".button").stream().filter(n->n instanceof Button b&&b.getText().equals("Open example")).map(n->(Button)n).toList();require(buttons.size()==3,"All three authored examples are directly discoverable");buttons.getFirst().fire();require(opened.size()==1&&examples.stream().anyMatch(e->e.name().equals(opened.getFirst().name())),"Example buttons invoke the real loading callback");for(var theme:UserPreferences.Theme.values()){var prefs=new UserPreferences(theme,UserPreferences.Language.ENGLISH,"en-US",6,13,100,8,5000000,UserPreferences.Motion.OFF,UserPreferences.Accent.OCEAN,UserPreferences.Density.COMFORTABLE);UiAppearance.install(prefs);home.applyCss();home.layout();GraphicExport.png(out.resolve("home-"+theme.name().toLowerCase(Locale.ROOT)+".png"),home,1);require(home.lookupAll(".studio-card").size()==7,"Task and teaching cards render in each appearance mode");}
 var sample=examples.getFirst().project();var report=new JsonObject();report.add("project",sample.deepCopy());report.add("results",new JsonObject());var privacy=new ReproducibilityDialog(stage,sample,report);privacy.dialog.show();require(!privacy.data.isSelected()&&!privacy.report.isSelected()&&privacy.report.isDisabled()&&privacy.plan.entries().size()==3,"Privacy dialog defaults exclude data and report");privacy.reviewed.setSelected(true);privacy.data.fire();require(!privacy.reviewed.isSelected()&&!privacy.report.isDisabled()&&privacy.plan.entries().stream().anyMatch(e->e.name().equals("project.json")),"Changing inclusion invalidates content review");privacy.report.fire();require(privacy.plan.entries().stream().anyMatch(e->e.name().equals("analysis.bsreport.json")),"Report inclusion is explicit after data inclusion");privacy.entries.setValue("analysis.bsreport.json");require(privacy.preview.getText().contains("observations"),"Review exposes complete historical report data");privacy.data.fire();require(!privacy.report.isSelected()&&privacy.report.isDisabled()&&privacy.plan.entries().stream().noneMatch(e->e.name().equals("project.json")||e.name().equals("analysis.bsreport.json")),"Disabling data also removes historical report");privacy.dialog.getDialogPane().applyCss();privacy.dialog.getDialogPane().layout();GraphicExport.png(out.resolve("privacy-review.png"),privacy.dialog.getDialogPane(),1);privacy.dialog.close();
 homeTaskGuardChecks();tablePerformance();progressChecks();}catch(Throwable problem){fail(problem);}}
 void homeTaskGuardChecks()throws Exception{Studio app=new Studio();var sidebar=Studio.class.getDeclaredField("sidebar");sidebar.setAccessible(true);sidebar.set(app,new VBox());var homeField=Studio.class.getDeclaredField("homeTab");homeField.setAccessible(true);Tab home=(Tab)homeField.get(app);int[] mutations={0};Button change=new Button("Replace project");change.setOnAction(e->mutations[0]++);home.setContent(new VBox(change));Task<Void> task=new Task<>(){protected Void call(){return null;}};var begin=Studio.class.getDeclaredMethod("beginTask",Task.class);begin.setAccessible(true);begin.invoke(app,task);require(home.getContent().isDisabled(),"Home source-changing controls are disabled while a calculation is active");change.fire();require(mutations[0]==0,"Disabled home actions cannot replace the computing source");var load=Studio.class.getDeclaredMethod("load",JsonObject.class,String.class);load.setAccessible(true);try{load.invoke(app,new JsonObject(),"Concurrent source replacement");throw new AssertionError("Project load allowed while calculating");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalStateException,"Programmatic load rejects active calculation before parsing or mutation");}task.cancel(true);require(!home.getContent().isDisabled(),"Home controls re-enable after cancellation");}
 void tablePerformance(){long before=System.nanoTime();TableView<String[]> table=new TableView<>();for(int j=0;j<8;j++){int column=j;TableColumn<String[],String> col=new TableColumn<>("Metric "+(j+1));col.setCellValueFactory(c->new javafx.beans.property.ReadOnlyStringWrapper(c.getValue()[column]));table.getColumns().add(col);}List<String[]> canonical=new ArrayList<>();for(int i=0;i<100000;i++){String[] row=new String[8];row[0]=Integer.toString((i*7919)%100000);for(int j=1;j<8;j++)row[j]="Case "+i+" / metric "+j;canonical.add(row);}table.getItems().setAll(canonical);TableTools.labels(table);BorderPane wrapped=TableTools.wrap(table);stage.getScene().setRoot(wrapped);wrapped.applyCss();wrapped.layout();measurements.addProperty("100000_by_8_table_construct_and_layout_ms",(System.nanoTime()-before)/1e6);before=System.nanoTime();table.getSortOrder().add(table.getColumns().getFirst());table.sort();measurements.addProperty("100000_numeric_rows_sort_ms",(System.nanoTime()-before)/1e6);require(table.getItems().getFirst()[0].equals("0")&&table.getItems().getLast()[0].equals("99999"),"Large table sorts numerically");var stored=(javafx.collections.ObservableList<?>)table.getProperties().get("brightstats.canonicalRows");require(stored.size()==100000&&stored.get(1)==canonical.get(1)&&canonical.get(1)[0].equals("7919"),"Large-table sorting leaves canonical rows/order untouched");List<String> mixed=Arrays.asList("2","10","1a","-3","—","NaN","∞","100","abc",null);for(String a:mixed)for(String b:mixed)for(String c:mixed)if(TableTools.compareCells(a,b)<=0&&TableTools.compareCells(b,c)<=0)require(TableTools.compareCells(a,c)<=0,"Mixed numeric/text comparison is transitive");List<String> shuffled=new ArrayList<>();Random random=new Random(9);for(int i=0;i<20000;i++)shuffled.add(mixed.get(random.nextInt(mixed.size())));shuffled.sort(TableTools::compareCells);require(shuffled.getFirst().equals("-3")&&shuffled.getLast()==null,"Mixed large sort has total ordering and no comparator-contract failure");require(table.lookupAll(".table-cell").size()<2000,"Large table renders virtualized cells rather than 800000 nodes");var preference=UiAppearance.current();for(String locale:List.of("en-US","en-GB","es-ES","fr-FR","de-DE","pt-BR","zh-CN","ja-JP","ar-SA","hi-IN")){UiAppearance.install(new UserPreferences(preference.theme(),preference.language(),locale,6,13,100,8,5000000,UserPreferences.Motion.OFF,preference.accent(),preference.density()));List<String> expected=java.util.stream.DoubleStream.of(-2e8,-12.5,-1e-8,0,1e-8,2,10,2e8).mapToObj(UiAppearance::number).toList();List<String> localized=new ArrayList<>(expected);Collections.reverse(localized);localized.sort(TableTools::compareCells);require(localized.equals(expected),"Localized decimal/scientific numeric ordering: "+locale);}UiAppearance.install(preference);}
 void progressChecks(){try{stage.getScene().setRoot(progress.content);Task<Void> working=new Task<>(){protected Void call(){return null;}};progress.elapsed.setText("99 seconds elapsed");progress.begin(working,"Known attempt count",10);require(progress.elapsed.getText().equals("0 seconds elapsed"),"Each calculation resets elapsed time before its first clock tick");progress.report(4);require(progress.bar.getProgress()==.4&&progress.completed==4,"Progress fraction uses actual reported count and explicit total");progress.expected(-1);require(progress.bar.getProgress()<0&&progress.count.getText().contains("total unavailable"),"Unknown total never becomes a fabricated percentage");progress.expected(3);require(progress.bar.getProgress()<0,"Out-of-range engine count is indeterminate rather than clamped to fake completion");working.setOnSucceeded(e->{try{require(progress.phase==CalculationProgressView.Phase.RENDERING,"Engine success remains distinct from rendering completion");progress.rendered();require(progress.phase==CalculationProgressView.Phase.COMPLETED&&progress.cancel.isDisabled(),"Final phase records that result view is ready");cancelCheck();}catch(Throwable problem){fail(problem);}});new Thread(working,"bright-stats-progress-check").start();}catch(Throwable problem){fail(problem);}}
 void cancelCheck(){Task<Void> task=new Task<>(){protected Void call()throws Exception{new java.util.concurrent.CountDownLatch(1).await();return null;}};progress.begin(task,"Cancellation check",-1);task.setOnRunning(e->progress.cancel.fire());task.setOnCancelled(e->{try{require(progress.phase==CalculationProgressView.Phase.CANCELLED&&progress.active==null,"Actual cancellation clears active state and retains cancelled phase");Task<Void> broken=new Task<>(){protected Void call(){throw new IllegalArgumentException("Intentional test failure");}};progress.begin(broken,"Failure check",-1);broken.setOnFailed(event->{try{require(progress.phase==CalculationProgressView.Phase.FAILED&&progress.active==null,"Actual task failure is reported without implying valid completion");finish();}catch(Throwable problem){fail(problem);}});new Thread(broken,"bright-stats-failure-check").start();}catch(Throwable problem){fail(problem);}});new Thread(task,"bright-stats-cancel-check").start();}
 void finish()throws Exception{progress.content.applyCss();progress.content.layout();GraphicExport.png(out.resolve("calculation-progress.png"),progress.content,1);JsonObject receipt=new JsonObject();receipt.addProperty("state","passed");receipt.addProperty("checks",checks);receipt.addProperty("table_rows",100000);receipt.add("measured_milliseconds",measurements);Files.writeString(out.resolve("receipt.json"),new GsonBuilder().setPrettyPrinting().create().toJson(receipt));System.out.println(receipt);stage.close();Platform.exit();}
 void fail(Throwable problem){failure=problem;problem.printStackTrace();stage.close();Platform.exit();}
 public static void main(String[] args){launch(args);if(failure!=null)System.exit(1);}
}
